import { ok, fail } from './result.js';
import { getCustomer } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';

/**
 * Check if a string is a valid date in YYYY-MM-DD format.
 * @param {string} dateStr
 * @returns {boolean}
 */
function isValidDate(dateStr) {
  const match = /^\d{4}-\d{2}-\d{2}$/.test(dateStr);
  if (!match) return false;
  const date = new Date(dateStr + 'T00:00:00Z');
  return date instanceof Date && !isNaN(date.getTime());
}

/**
 * Calculate the total amount for a single line item.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number} qty × unitPrice in cents
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number }> }} invoice
 * @returns {{ subtotal: number, total: number }} both in cents
 */
export function invoiceTotals(invoice) {
  let subtotal = 0;
  for (const line of invoice.lines) {
    subtotal += lineTotal(line);
  }
  return { subtotal, total: subtotal };
}

/**
 * Add or update a line on a draft invoice.
 * @param {{ status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: unknown }} input
 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty }) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  const product = getProduct(sku);
  if (!product.ok) {
    return product;
  }

  const existingLineIndex = invoice.lines.findIndex((line) => line.sku === sku);

  let newLines;
  if (existingLineIndex >= 0) {
    newLines = invoice.lines.map((line, index) => {
      if (index === existingLineIndex) {
        return { ...line, qty: line.qty + qty };
      }
      return { ...line };
    });
  } else {
    newLines = [
      ...invoice.lines.map((line) => ({ ...line })),
      {
        sku,
        name: product.value.name,
        qty,
        unitPrice: product.value.unitPrice,
        vatRate: product.value.vatRate,
      },
    ];
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);

  if (lineIndex < 0) {
    return fail('LINE_NOT_FOUND');
  }

  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  const newLines = invoice.lines.filter((line) => line.sku !== sku).map((line) => ({ ...line }));

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
 * @param {{ status: string, issueDate: string, lines: Array }} invoice
 * @param {string[]} existingNumbers
 * @returns {{ ok: true, value: { status: string, number: string, lines: Array } } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

/**
 * Create a draft invoice with the given customer and line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: unknown }> }} input
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  if (!isValidDate(issueDate)) {
    return fail('DATE_INVALID');
  }

  const customer = getCustomer(customerId);
  if (!customer.ok) {
    return customer;
  }

  if (!lines || lines.length === 0) {
    return fail('NO_LINES');
  }

  const invoiceLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    const product = getProduct(line.sku);
    if (!product.ok) {
      return product;
    }

    invoiceLines.push({
      sku: line.sku,
      name: product.value.name,
      qty: line.qty,
      unitPrice: product.value.unitPrice,
      vatRate: product.value.vatRate,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

